package com.sih.learningplatform.service;
import com.sih.learningplatform.dto.*; import com.sih.learningplatform.entity.*; import com.sih.learningplatform.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*;
@Service @RequiredArgsConstructor public class DashboardService { private final EmployeeRepository employees; private final RoleCompetencyRepository roles; private final LearningMaterialRepository materials; private final QuizRepository quizzes;
 public DashboardOverview getOverview(){var es=employees.findAll(); Map<String,RoleCompetency> rs=roles.findAll().stream().collect(Collectors.toMap(r->r.getDesignation().toLowerCase(),r->r)); Map<String,Long> gaps=new HashMap<>(); var att=es.stream().map(e->{var r=rs.get(e.getDesignation().toLowerCase()); if(r==null)return null; Set<String> c=e.getCurrentSkills().stream().map(String::toLowerCase).collect(Collectors.toSet()); var m=r.getRequiredSkills().stream().filter(s->!c.contains(s.toLowerCase())).toList();m.forEach(s->gaps.merge(s,1L,Long::sum));double score=r.getRequiredSkills().isEmpty()?100:(r.getRequiredSkills().size()-m.size())*100.0/r.getRequiredSkills().size();String p=m.size()>=3?"Critical":m.size()==2?"High":m.size()==1?"Moderate":"On Track";return DashboardOverview.EmployeeAttention.builder().employeeId(e.getId()).employeeName(e.getName()).designation(e.getDesignation()).competencyScore(Math.round(score*100)/100.0).missingSkills(m.size()).priority(p).build();}).filter(Objects::nonNull).sorted(Comparator.comparingInt(DashboardOverview.EmployeeAttention::getMissingSkills).reversed()).toList();double avg=att.stream().mapToDouble(DashboardOverview.EmployeeAttention::getCompetencyScore).average().orElse(100);var tg=gaps.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(4).map(x->DashboardOverview.SkillGap.builder().skill(x.getKey()).affectedEmployees(x.getValue()).build()).toList();long critical=att.stream().filter(x->x.getPriority().equals("Critical")).count();return DashboardOverview.builder().totalEmployees(es.size()).activeLearningPrograms(materials.count()).generatedQuizzes(quizzes.count()).averageCompetencyScore(Math.round(avg*100)/100.0).criticalSkillGaps(critical).employeesNeedingAttention(att.stream().limit(5).toList()).topSkillGaps(tg).build(); }
}
